<?php
require_once __DIR__.'/../config/conexao.php';$id=(int)($_GET['id']??0);
$s=$pdo->prepare("SELECT f.*,t.nome transportador,t.documento,t.telefone,eo.identificacao origem,eo.logradouro logradouro_origem,eo.cidade cidade_origem,eo.estado uf_origem,ed.identificacao destino,ed.logradouro logradouro_destino,ed.cidade cidade_destino,ed.estado uf_destino FROM fretes f JOIN transportadores t ON t.id=f.transportador_id JOIN enderecos eo ON eo.id=f.origem_id JOIN enderecos ed ON ed.id=f.destino_id WHERE f.id=?");$s->execute([$id]);$frete=$s->fetch();
if(!$frete){http_response_code(404);exit('Frete não encontrado.');}
$p=$pdo->prepare("SELECT pr.nome,pr.descricao,pr.peso FROM frete_produtos fp JOIN produtos pr ON pr.id=fp.produto_id WHERE fp.frete_id=? ORDER BY pr.nome");$p->execute([$id]);$produtos=$p->fetchAll();$pesoTotal=array_sum(array_column($produtos,'peso'));
$titulo='Detalhes do frete #'.$id;include __DIR__.'/../includes/topo.php';?>
<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h2 page-title">Frete #<?=$id?></h1><a class="btn btn-outline-secondary" href="index.php">Voltar</a></div>
<div class="row g-3 mb-3"><div class="col-md-4"><div class="card p-3"><div class="text-muted small">Data do frete</div><strong><?=date('d/m/Y',strtotime($frete['data_frete']))?></strong></div></div><div class="col-md-4"><div class="card p-3"><div class="text-muted small">Transportador</div><strong><?=htmlspecialchars($frete['transportador'])?></strong><small><?=htmlspecialchars($frete['telefone']??'')?></small></div></div><div class="col-md-4"><div class="card p-3"><div class="text-muted small">Peso total</div><strong><?=number_format($pesoTotal,2,',','.')?> kg</strong></div></div></div>
<div class="row g-3 mb-3"><div class="col-md-6"><div class="card p-3"><h2 class="h5">Origem</h2><strong><?=htmlspecialchars($frete['origem'])?></strong><div><?=htmlspecialchars(($frete['logradouro_origem']??'').' — '.$frete['cidade_origem'].'/'.$frete['uf_origem'])?></div></div></div><div class="col-md-6"><div class="card p-3"><h2 class="h5">Destino</h2><strong><?=htmlspecialchars($frete['destino'])?></strong><div><?=htmlspecialchars(($frete['logradouro_destino']??'').' — '.$frete['cidade_destino'].'/'.$frete['uf_destino'])?></div></div></div></div>
<div class="card p-3"><h2 class="h5">Produtos transportados</h2><div class="table-responsive"><table class="table"><thead><tr><th>Produto</th><th>Descrição</th><th>Peso</th></tr></thead><tbody><?php foreach($produtos as $pr):?><tr><td><?=htmlspecialchars($pr['nome'])?></td><td><?=htmlspecialchars($pr['descricao']??'')?></td><td><?=number_format((float)$pr['peso'],2,',','.')?> kg</td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="2">Peso total</th><th><?=number_format($pesoTotal,2,',','.')?> kg</th></tr></tfoot></table></div></div>
<?php include __DIR__.'/../includes/rodape.php';?>
